assets = {"PC-001": "win", "PC-002": "win", "MAC-101": "mac", "MAC-102": "mac", "PC-003": "win"}
edr = {"PC-001", "PC-002", "MAC-101", "PC-003"}
mdm = {"MAC-101"}
nac = {"PC-001", "PC-002", "MAC-101", "MAC-102", "PC-003", "PHONE-77"}
for host, os_ in sorted(assets.items()):
    miss = [n for n, s in (("EDR", edr), ("NAC", nac)) if host not in s]
    if os_ == "mac" and host not in mdm:
        miss.append("MDM")
    if miss:
        print(host, "빠짐:", ",".join(miss))
print("대장에 없는데 NAC 에 붙은 기기:", sorted(nac - assets.keys()))
# MAC-102 빠짐: EDR,MDM
# 대장에 없는데 NAC 에 붙은 기기: ['PHONE-77']

bad = {"evil-cdn.example", "login-tmap.example"}
proxy = [("PC-001", "www.tmap.co.kr"), ("PC-002", "login-tmap.example"),
         ("MAC-101", "img.evil-cdn.example"), ("PC-003", "notevil-cdn.example")]
for pc, host in proxy:
    if any(host == d or host.endswith("." + d) for d in bad):
        print("IoC 일치:", pc, host)
# IoC 일치: PC-002 login-tmap.example
# IoC 일치: MAC-101 img.evil-cdn.example
